import { Ionicons } from '@expo/vector-icons';
import * as WebBrowser from 'expo-web-browser';
import { randomUUID } from 'expo-crypto';
import { StatusBar } from 'expo-status-bar';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, FlatList, Image, ImageBackground, KeyboardAvoidingView, Linking, Platform, Pressable, RefreshControl, SafeAreaView, ScrollView, StyleSheet, Text, View } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { api, ApiError, query } from './src/api';
import { SUPPORT_EMAIL, SUPPORT_WHATSAPP, WEB_URL } from './src/config';
import { AuthProvider, CartProvider, ThemeProvider, useAuth, useCart, useTheme } from './src/providers';
import type { Booking, CartItem, CartQuote, Category, Listing, Order, PaymentMethod, Review, Vendor } from './src/types';
import { BrandMark, Button, Card, Chip, Divider, EmptyState, Field, Header, IconButton, Money, Notice, Sheet, Spinner } from './src/ui';

const WELCOME_KEY = 'sokoni_mobile_welcome_complete';
type Screen = 'welcome' | 'home' | 'browse' | 'cart' | 'account' | 'login' | 'register' | 'pin' | 'pinsetup' | 'forgot' | 'listing' | 'store' | 'checkout' | 'orders' | 'bookings' | 'track' | 'booking' | 'support';
type Nav = { screen: Screen; params?: Record<string, any> };
const icons: Record<string, keyof typeof Ionicons.glyphMap> = { Food: 'restaurant-outline', Fashion: 'shirt-outline', Beauty: 'sparkles-outline', Electronics: 'phone-portrait-outline', Home: 'home-outline', Services: 'construct-outline' };
const message = (error: unknown) => error instanceof ApiError ? error.message : error instanceof Error ? error.message : 'Something went wrong. Please try again.';
const date = (value?: string | null) => value ? new Date(value).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : 'To be arranged';
const statusLabel = (value: string) => value.replace(/_/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());

export default function App() {
  return <ThemeProvider><AuthProvider><CartProvider><Marketplace /></CartProvider></AuthProvider></ThemeProvider>;
}

function Marketplace() {
  const { colors, theme } = useTheme();
  const auth = useAuth();
  const [welcomeLoaded, setWelcomeLoaded] = useState(false);
  const [seenWelcome, setSeenWelcome] = useState(false);
  const [nav, setNav] = useState<Nav>({ screen: 'home' });
  const history = useRef<Nav[]>([]);
  useEffect(() => { AsyncStorage.getItem(WELCOME_KEY).then((value) => { setSeenWelcome(value === 'yes'); setWelcomeLoaded(true); }).catch(() => setWelcomeLoaded(true)); }, []);
  const go = useCallback((screen: Screen, params?: Record<string, any>) => { history.current.push(nav); setNav({ screen, params }); }, [nav]);
  const back = useCallback(() => { const previous = history.current.pop(); setNav(previous || { screen: 'home' }); }, []);
  const finishWelcome = useCallback(async (destination: Screen = 'home') => { await AsyncStorage.setItem(WELCOME_KEY, 'yes'); setSeenWelcome(true); history.current = []; setNav({ screen: destination }); }, []);
  const tab = (screen: Screen) => { history.current = []; setNav({ screen }); };

  if (!welcomeLoaded || auth.loading) return <SafeAreaView style={[styles.app, { backgroundColor: colors.bg }]}><Spinner label="Preparing Sokoni Hub…" /></SafeAreaView>;
  const current = !seenWelcome ? 'welcome' : nav.screen;
  const common = { go, back, tab };
  let body: React.ReactNode;
  if (current === 'welcome') body = <Welcome onDone={finishWelcome} />;
  else if (auth.user && auth.user.role !== 'buyer') body = <WebOnlyAccount onSignOut={auth.logout} />;
  else if (current === 'home') body = <Home {...common} />;
  else if (current === 'browse') body = <Browse {...common} initial={nav.params} />;
  else if (current === 'cart') body = <Cart {...common} />;
  else if (current === 'account') body = <Account {...common} />;
  else if (current === 'login') body = <Login {...common} />;
  else if (current === 'register') body = <Register {...common} />;
  else if (current === 'pin') body = <Pin {...common} setup={false} />;
  else if (current === 'pinsetup') body = <Pin {...common} setup />;
  else if (current === 'forgot') body = <Recovery {...common} params={nav.params} />;
  else if (current === 'listing') body = <ListingDetail {...common} id={nav.params?.id} />;
  else if (current === 'store') body = <StoreDetail {...common} slug={nav.params?.slug} />;
  else if (current === 'checkout') body = <Checkout {...common} />;
  else if (current === 'orders') body = <Orders {...common} />;
  else if (current === 'bookings') body = <Bookings {...common} />;
  else if (current === 'track') body = <Track {...common} params={nav.params} />;
  else if (current === 'booking') body = <BookService {...common} listing={nav.params?.listing} />;
  else body = <Support {...common} />;
  return <SafeAreaView style={[styles.app, { backgroundColor: colors.bg }]}><StatusBar style={theme === 'dark' ? 'light' : 'dark'} />{body}</SafeAreaView>;
}

function Welcome({ onDone }: { onDone: (screen?: Screen) => void }) {
  const { colors } = useTheme(); const [page, setPage] = useState(0); const ref = useRef<FlatList>(null);
  const slides = [
    ['A market made for your neighbourhood', 'Find trusted local products and services, all in one simple place.', 'storefront-outline'],
    ['Shop with confidence', 'Clear prices, direct vendors, secure sign-in and status updates from checkout to delivery.', 'shield-checkmark-outline'],
    ['Your next find is nearby', 'Browse as a guest or create your free buyer account to order, book and track with ease.', 'heart-outline'],
  ] as const;
  return <ImageBackground source={require('./assets/hero.jpg')} resizeMode="cover" style={styles.welcomeBg}><View style={[styles.welcomeOverlay, { backgroundColor: colors.overlay }]}><View style={styles.welcomeTop}><BrandMark /></View><FlatList ref={ref} data={slides} horizontal pagingEnabled showsHorizontalScrollIndicator={false} onMomentumScrollEnd={(e) => setPage(Math.round(e.nativeEvent.contentOffset.x / e.nativeEvent.layoutMeasurement.width))} renderItem={({ item }) => <View style={styles.welcomeSlide}><View style={[styles.welcomeIcon, { backgroundColor: colors.goldSoft }]}><Ionicons name={item[2]} size={40} color={colors.gold}/></View><Text style={styles.welcomeTitle}>{item[0]}</Text><Text style={styles.welcomeText}>{item[1]}</Text></View>} keyExtractor={(_, index) => String(index)}/><View style={styles.dots}>{slides.map((_, index) => <View key={index} style={[styles.dot, { backgroundColor: index === page ? colors.gold : 'rgba(255,255,255,.45)' }]} />)}</View><View style={styles.welcomeActions}>{page < 2 ? <Button onPress={() => ref.current?.scrollToIndex({ index: page + 1 })} variant="gold">Continue</Button> : <><Button onPress={() => onDone('register')} variant="gold">Create a buyer account</Button><Button onPress={() => onDone('login')} variant="secondary">Sign in</Button></>}<Pressable onPress={() => onDone('home')}><Text style={styles.browseGuest}>Browse as a guest</Text></Pressable></View></View></ImageBackground>;
}

function Tabs({ active, tab }: { active: Screen; tab: (screen: Screen) => void }) { const { colors } = useTheme(); const { count } = useCart(); const items: [Screen, keyof typeof Ionicons.glyphMap, string][] = [['home','home-outline','Home'],['browse','search-outline','Browse'],['cart','bag-outline','Cart'],['account','person-outline','Account']]; return <View style={[styles.tabs, { backgroundColor: colors.tab, borderColor: colors.border }]}>{items.map(([screen, icon, label]) => <Pressable key={screen} onPress={() => tab(screen)} style={styles.tab}><View>{<Ionicons name={active === screen ? icon.replace('-outline','') as keyof typeof Ionicons.glyphMap : icon} size={22} color={active === screen ? colors.primary : colors.muted}/>} {screen === 'cart' && count > 0 ? <View style={[styles.tabBadge, { backgroundColor: colors.gold }]}><Text style={styles.tabBadgeText}>{count}</Text></View> : null}</View><Text style={[styles.tabText, { color: active === screen ? colors.primary : colors.muted }]}>{label}</Text></Pressable>)}</View>; }

function Home({ go, tab }: any) {
  const { colors } = useTheme(); const { user } = useAuth(); const { count } = useCart(); const [categories, setCategories] = useState<Category[]>([]); const [products, setProducts] = useState<Listing[]>([]); const [services, setServices] = useState<Listing[]>([]); const [refreshing, setRefreshing] = useState(false); const [error, setError] = useState('');
  const load = useCallback(async () => { setError(''); try { const [c, p, s] = await Promise.all([api.get<{categories: Category[]}>('/meta/categories'), api.get<{listings: Listing[]}>('/listings?kind=product&limit=8'), api.get<{listings: Listing[]}>('/listings?kind=service&limit=8')]); setCategories(c.categories); setProducts(p.listings); setServices(s.listings); } catch (e) { setError(message(e)); } }, []);
  useEffect(() => { void load(); }, [load]);
  return <View style={styles.page}><ScrollView refreshControl={<RefreshControl refreshing={refreshing} onRefresh={async () => { setRefreshing(true); await load(); setRefreshing(false); }} tintColor={colors.primary} />} contentContainerStyle={styles.scroll}><View style={styles.homeHead}><BrandMark small/><View style={styles.homeHeadRight}>{user ? <Text style={[styles.hello, { color: colors.text2 }]}>Hi, {user.full_name.split(' ')[0]}</Text> : <Pressable onPress={() => go('login')}><Text style={[styles.signInLink, { color: colors.primary }]}>Sign in</Text></Pressable>}<IconButton icon="bag-outline" label="Cart" badge={count} onPress={() => tab('cart')}/></View></View><Pressable onPress={() => go('browse')} style={[styles.search, { backgroundColor: colors.surface, borderColor: colors.border }]}><Ionicons name="search" size={20} color={colors.muted}/><Text style={[styles.searchText, { color: colors.muted }]}>Search products, services and stores</Text></Pressable><View style={[styles.heroCard, { backgroundColor: colors.primary }]}><Text style={styles.heroEyebrow}>LOCAL MARKETPLACE</Text><Text style={styles.heroTitle}>Everything local,{`\n`}in one trusted place.</Text><Text style={styles.heroCopy}>Discover independent sellers and skilled service providers near you.</Text><Pressable onPress={() => go('browse')} style={[styles.heroCta, { backgroundColor: colors.gold }]}><Text style={styles.heroCtaText}>Explore marketplace</Text><Ionicons name="arrow-forward" size={17} color="#161B36"/></Pressable></View>{error ? <Notice type="warning">{error}</Notice> : null}<SectionTitle title="Shop by category" action="See all" onPress={() => go('browse')}/><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.categoryRail}>{categories.map((category, index) => <Pressable key={category.id} onPress={() => go('browse', { category: category.slug, kind: category.kind })} style={[styles.category, { backgroundColor: index % 2 ? colors.tealSoft : colors.goldSoft }]}><View style={[styles.categoryIcon, { backgroundColor: colors.surface }]}><Ionicons name={icons[category.name] || (category.kind === 'service' ? 'construct-outline' : 'cube-outline')} size={22} color={index % 2 ? colors.teal : colors.gold}/></View><Text numberOfLines={2} style={[styles.categoryName, { color: colors.text }]}>{category.name}</Text><Text style={[styles.categoryKind, { color: colors.text2 }]}>{category.kind === 'service' ? 'Service' : 'Products'}</Text></Pressable>)}</ScrollView><ListingRail title="Fresh finds" listings={products} onSelect={(id) => go('listing', { id })} onMore={() => go('browse', { kind: 'product' })}/><ListingRail title="Book a local service" listings={services} onSelect={(id) => go('listing', { id })} onMore={() => go('browse', { kind: 'service' })}/><View style={{ height: 30 }}/></ScrollView><Tabs active="home" tab={tab}/></View>;
}

function SectionTitle({ title, action, onPress }: { title: string; action?: string; onPress?: () => void }) { const { colors } = useTheme(); return <View style={styles.sectionTitle}><Text style={[styles.sectionHeading, { color: colors.text }]}>{title}</Text>{action && <Pressable onPress={onPress}><Text style={[styles.seeAll, { color: colors.primary }]}>{action}</Text></Pressable>}</View>; }
function ListingRail({ title, listings, onSelect, onMore }: { title: string; listings: Listing[]; onSelect: (id: string) => void; onMore: () => void }) { const { colors } = useTheme(); return <><SectionTitle title={title} action="See all" onPress={onMore}/>{listings.length ? <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.listingRail}>{listings.map((listing) => <ListingCard key={listing.id} listing={listing} onPress={() => onSelect(listing.id)} compact/>)}</ScrollView> : <View style={[styles.railEmpty, { backgroundColor: colors.surface2 }]}><Text style={{ color: colors.text2 }}>Nothing to show here yet.</Text></View>}</>; }
function ListingCard({ listing, onPress, compact = false }: { listing: Listing; onPress: () => void; compact?: boolean }) { const { colors } = useTheme(); const image = listing.images?.[0]; return <Pressable onPress={onPress} style={[styles.listingCard, compact && styles.listingCardCompact, { backgroundColor: colors.surface, borderColor: colors.border }]}>{image ? <Image source={{ uri: image }} style={styles.listingImage}/> : <View style={[styles.listingImage, { backgroundColor: colors.primarySoft }]}><Ionicons name={listing.kind === 'service' ? 'construct-outline' : 'cube-outline'} size={29} color={colors.primary}/></View>}<View style={styles.listingInfo}><Text numberOfLines={2} style={[styles.listingTitle, { color: colors.text }]}>{listing.title}</Text><Text numberOfLines={1} style={[styles.listingVendor, { color: colors.text2 }]}>{listing.business_name || listing.vendor_city || 'Local seller'}</Text><Money value={listing.price} currency={listing.currency} strong={!compact}/>{listing.kind === 'service' && <Text style={[styles.servicePill, { color: colors.teal, backgroundColor: colors.tealSoft }]}>SERVICE</Text>}</View></Pressable>; }

function Browse({ go, back, tab, initial }: any) {
  const { colors } = useTheme(); const [q, setQ] = useState(initial?.q || ''); const [kind, setKind] = useState<string>(initial?.kind || ''); const [category, setCategory] = useState(initial?.category || ''); const [sort, setSort] = useState('newest'); const [listings, setListings] = useState<Listing[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [loading, setLoading] = useState(true); const [sheet, setSheet] = useState(false); const [min, setMin] = useState(''); const [max, setMax] = useState('');
  const load = useCallback(async () => { setLoading(true); try { const [rows, cats] = await Promise.all([api.get<{listings: Listing[]}>(`/listings${query({ q, kind, category, sort, min, max, limit: 50 })}`), api.get<{categories: Category[]}>('/meta/categories')]); setListings(rows.listings); setCategories(cats.categories); } catch (e) { Alert.alert('Could not load marketplace', message(e)); } finally { setLoading(false); } }, [q, kind, category, sort, min, max]);
  useEffect(() => { const timer = setTimeout(() => void load(), 250); return () => clearTimeout(timer); }, [load]);
  return <View style={styles.page}><Header title="Browse marketplace" back={back} right={<IconButton icon="options-outline" label="Filters" onPress={() => setSheet(true)}/>}/><View style={styles.browseSearch}><Ionicons name="search" size={20} color={colors.muted}/><Field label="" value={q} onChangeText={setQ} placeholder="Search local products or services" style={styles.inlineField}/></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.filterRail}><Chip selected={!kind} onPress={() => setKind('')}>Everything</Chip><Chip selected={kind === 'product'} onPress={() => setKind(kind === 'product' ? '' : 'product')}>Products</Chip><Chip selected={kind === 'service'} onPress={() => setKind(kind === 'service' ? '' : 'service')}>Services</Chip>{categories.filter((cat) => !kind || cat.kind === kind).map((cat) => <Chip key={cat.id} selected={category === cat.slug} onPress={() => setCategory(category === cat.slug ? '' : cat.slug)}>{cat.name}</Chip>)}</ScrollView><View style={styles.resultsLine}><Text style={[styles.resultText, { color: colors.text2 }]}>{loading ? 'Searching…' : `${listings.length} result${listings.length === 1 ? '' : 's'}`}</Text><Pressable onPress={() => setSheet(true)}><Text style={[styles.sortText, { color: colors.primary }]}>{statusLabel(sort)}</Text></Pressable></View>{loading ? <Spinner label="Finding the best local picks…"/> : <FlatList data={listings} keyExtractor={(item) => item.id} contentContainerStyle={styles.browseList} renderItem={({ item }) => <ListingCard listing={item} onPress={() => go('listing', { id: item.id })}/>} ListEmptyComponent={<EmptyState title="No matching listings" text="Try another search or clear a filter." icon="search-outline" action={<Button style={{ marginTop: 8 }} variant="secondary" onPress={() => { setQ(''); setKind(''); setCategory(''); }}>Clear filters</Button>}/>}/>}<Tabs active="browse" tab={tab}/><Sheet visible={sheet} title="Filter & sort" onClose={() => setSheet(false)}><Text style={[styles.sheetLabel, { color: colors.text }]}>Sort results</Text>{[['newest','Newest first'],['popular','Most popular'],['price_asc','Price: low to high'],['price_desc','Price: high to low']].map(([value, label]) => <Pressable key={value} onPress={() => setSort(value)} style={styles.radioRow}><Ionicons name={sort === value ? 'radio-button-on' : 'radio-button-off'} size={22} color={sort === value ? colors.primary : colors.muted}/><Text style={[styles.radioText, { color: colors.text }]}>{label}</Text></Pressable>)}<Divider/><View style={styles.priceFields}><View style={{ flex: 1 }}><Field label="Minimum (QAR)" value={min} onChangeText={setMin} keyboardType="decimal-pad" placeholder="0"/></View><View style={{ flex: 1 }}><Field label="Maximum (QAR)" value={max} onChangeText={setMax} keyboardType="decimal-pad" placeholder="Any"/></View></View><Button onPress={() => setSheet(false)}>Show results</Button></Sheet></View>;
}

function AuthScaffold({ title, subtitle, children, back }: { title: string; subtitle: string; children: React.ReactNode; back: () => void }) { const { colors } = useTheme(); return <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.authPage}><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.authScroll}><Pressable onPress={back} style={styles.authBack}><Ionicons name="arrow-back" size={24} color={colors.text}/></Pressable><BrandMark/><Text style={[styles.authTitle, { color: colors.text }]}>{title}</Text><Text style={[styles.authSubtitle, { color: colors.text2 }]}>{subtitle}</Text>{children}</ScrollView></KeyboardAvoidingView>; }
function Login({ go, back }: any) { const { colors } = useTheme(); const auth = useAuth(); const [identifier, setIdentifier] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const submit = async () => { if (!identifier.trim() || !password) return Alert.alert('Enter your details', 'Use your email or phone number and password.'); setBusy(true); try { const stage = await auth.login(identifier, password); if (stage.kind === 'pin') go('pin'); else if (stage.kind === 'setup') go('pinsetup'); else if (stage.kind === 'mfa') Alert.alert('Web-only account', 'Administrators use the secure web portal.'); else go('account'); } catch (e) { Alert.alert('Sign-in failed', message(e)); } finally { setBusy(false); } }; return <AuthScaffold title="Welcome back" subtitle="Sign in first, then confirm your four-digit PIN." back={back}><Field label="Email address or phone number" value={identifier} onChangeText={setIdentifier} autoCapitalize="none" autoComplete="username" placeholder="you@example.com or +974…"/><Field label="Password" value={password} onChangeText={setPassword} secureTextEntry autoComplete="password" placeholder="Your password"/><Pressable onPress={() => go('forgot', { purpose: 'password' })}><Text style={[styles.forgot, { color: colors.primary }]}>Forgot password?</Text></Pressable><Button loading={busy} onPress={submit} style={{ marginTop: 18 }}>Continue to PIN</Button><Divider/><Text style={[styles.authSwitch, { color: colors.text2 }]}>New to Sokoni Hub? <Text onPress={() => go('register')} style={{ color: colors.primary, fontWeight: '800' }}>Create an account</Text></Text><Pressable onPress={() => WebBrowser.openBrowserAsync(WEB_URL)}><Text style={[styles.webPortalLink, { color: colors.text2 }]}>Selling or managing Sokoni Hub? Use the web portal.</Text></Pressable></AuthScaffold>; }
function Register({ go, back }: any) { const { colors } = useTheme(); const auth = useAuth(); const [form, setForm] = useState({ full_name: '', phone: '', email: '', password: '', pin: '', confirm: '' }); const [busy, setBusy] = useState(false); const set = (key: keyof typeof form) => (value: string) => setForm((old) => ({ ...old, [key]: value })); const submit = async () => { if (!form.full_name || !form.phone || !form.email || !form.password || !form.pin) return Alert.alert('Complete the form', 'Every field is required for a secure buyer account.'); if (form.password.length < 12) return Alert.alert('Choose a longer password', 'Use at least 12 characters.'); if (form.pin !== form.confirm) return Alert.alert('PINs do not match', 'Please enter the same four-digit PIN twice.'); setBusy(true); try { await auth.register(form); go('account'); } catch (e) { Alert.alert('Could not create account', message(e)); } finally { setBusy(false); } }; return <AuthScaffold title="Create your account" subtitle="A buyer account lets you order, book and track securely." back={back}><Field label="Full name" value={form.full_name} onChangeText={set('full_name')} autoComplete="name" placeholder="Your name"/><Field label="Phone number" value={form.phone} onChangeText={set('phone')} keyboardType="phone-pad" placeholder="+974…"/><Field label="Email address" value={form.email} onChangeText={set('email')} autoCapitalize="none" keyboardType="email-address" autoComplete="email" placeholder="you@example.com"/><Field label="Password" value={form.password} onChangeText={set('password')} secureTextEntry autoComplete="new-password" placeholder="At least 12 characters"/><Field label="Choose a 4-digit PIN" value={form.pin} onChangeText={set('pin')} secureTextEntry keyboardType="number-pad" maxLength={4} placeholder="••••"/><Field label="Confirm your PIN" value={form.confirm} onChangeText={set('confirm')} secureTextEntry keyboardType="number-pad" maxLength={4} placeholder="••••"/><Notice>Keep your PIN private. Avoid simple sequences or digits from your phone number.</Notice><Button loading={busy} onPress={submit} style={{ marginTop: 8 }}>Create secure account</Button><Text style={[styles.terms, { color: colors.text2 }]}>By continuing, you agree to Sokoni Hub's terms and privacy policy.</Text><Text style={[styles.authSwitch, { color: colors.text2 }]}>Already registered? <Text onPress={() => go('login')} style={{ color: colors.primary, fontWeight: '800' }}>Sign in</Text></Text></AuthScaffold>; }
function Pin({ go, back, setup }: any) { const { colors } = useTheme(); const auth = useAuth(); const [pin, setPin] = useState(''); const [email, setEmail] = useState(''); const [busy, setBusy] = useState(false); const submit = async () => { if (pin.length !== 4) return Alert.alert('Enter your PIN', 'Your PIN must contain exactly four digits.'); setBusy(true); try { if (setup) await auth.setupPin(pin, email || undefined); else await auth.verifyPin(pin); go('account'); } catch (e) { Alert.alert(setup ? 'Could not save PIN' : 'PIN not accepted', message(e)); setPin(''); } finally { setBusy(false); } }; return <AuthScaffold title={setup ? 'Set your secure PIN' : `Hello${auth.stage.kind === 'pin' ? `, ${auth.stage.fullName.split(' ')[0]}` : ''}`} subtitle={setup ? 'Your account needs a unique four-digit PIN to protect every sign-in.' : 'Enter your four-digit PIN to finish signing in.'} back={back}>{setup && auth.stage.kind === 'setup' && auth.stage.needsEmail ? <Field label="Recovery email address" value={email} onChangeText={setEmail} keyboardType="email-address" autoCapitalize="none" placeholder="you@example.com"/> : null}<Field label="4-digit PIN" value={pin} onChangeText={setPin} secureTextEntry keyboardType="number-pad" maxLength={4} placeholder="••••" style={styles.pinField}/><Button loading={busy} onPress={submit}>{setup ? 'Save PIN and continue' : 'Unlock account'}</Button>{!setup && <Pressable onPress={() => go('forgot', { purpose: 'pin' })}><Text style={[styles.forgot, { color: colors.primary }]}>Forgot PIN?</Text></Pressable>}<Notice type="warning">For your protection, repeated incorrect PIN entries are temporarily locked.</Notice></AuthScaffold>; }
function Recovery({ go, back, params }: any) { const { colors } = useTheme(); const initial = params?.purpose === 'pin' ? 'pin' : 'password'; const [purpose, setPurpose] = useState<'password' | 'pin'>(initial); const [email, setEmail] = useState(''); const [code, setCode] = useState(''); const [secret, setSecret] = useState(''); const [confirm, setConfirm] = useState(''); const [requested, setRequested] = useState(false); const [busy, setBusy] = useState(false); const request = async () => { if (!email) return Alert.alert('Enter your email', 'Use the email registered on your buyer account.'); setBusy(true); try { await api.post('/auth/recovery/request', { email, purpose }); setRequested(true); Alert.alert('Check your inbox', 'If that address can receive recovery email, a one-time code will arrive shortly.'); } catch (e) { Alert.alert('Could not start recovery', message(e)); } finally { setBusy(false); } }; const reset = async () => { if (code.length !== 6 || !secret) return Alert.alert('Complete the form', 'Enter the six-digit email code and your new credential.'); if (secret !== confirm) return Alert.alert('Does not match', 'Please enter the same new value twice.'); if (purpose === 'password' && secret.length < 12) return Alert.alert('Choose a longer password', 'Use at least 12 characters.'); if (purpose === 'pin' && !/^\d{4}$/.test(secret)) return Alert.alert('PIN required', 'Use exactly four digits.'); setBusy(true); try { await api.post('/auth/recovery/complete', purpose === 'password' ? { email, purpose, code, new_password: secret } : { email, purpose, code, new_pin: secret }); Alert.alert('Updated securely', `Your ${purpose === 'password' ? 'password' : 'PIN'} has been reset. Sign in again.`); go('login'); } catch (e) { Alert.alert('Could not reset', message(e)); } finally { setBusy(false); } }; return <AuthScaffold title={`Recover ${purpose === 'password' ? 'password' : 'PIN'}`} subtitle="Recovery emails work as soon as Sokoni Hub email delivery is enabled. We never reveal whether an account exists." back={back}><View style={styles.recoveryTabs}><Chip selected={purpose === 'password'} onPress={() => { setPurpose('password'); setRequested(false); }}>Password</Chip><Chip selected={purpose === 'pin'} onPress={() => { setPurpose('pin'); setRequested(false); }}>PIN</Chip></View><Field label="Your account email" value={email} onChangeText={setEmail} autoCapitalize="none" keyboardType="email-address" placeholder="you@example.com" editable={!requested}/>{!requested ? <Button loading={busy} onPress={request}>Email me a recovery code</Button> : <><Notice type="success">A short-lived one-time code was requested. It is valid for 15 minutes.</Notice><Field label="6-digit recovery code" value={code} onChangeText={setCode} keyboardType="number-pad" maxLength={6} placeholder="••••••"/><Field label={purpose === 'password' ? 'New password' : 'New 4-digit PIN'} value={secret} onChangeText={setSecret} secureTextEntry keyboardType={purpose === 'pin' ? 'number-pad' : 'default'} maxLength={purpose === 'pin' ? 4 : undefined} placeholder={purpose === 'password' ? 'At least 12 characters' : '••••'}/><Field label="Confirm new value" value={confirm} onChangeText={setConfirm} secureTextEntry keyboardType={purpose === 'pin' ? 'number-pad' : 'default'} maxLength={purpose === 'pin' ? 4 : undefined} placeholder="Repeat it"/><Button loading={busy} onPress={reset}>Reset securely</Button><Pressable onPress={() => { setRequested(false); setCode(''); }}><Text style={[styles.forgot, { color: colors.primary }]}>Request a new code</Text></Pressable></>}</AuthScaffold>; }

function ListingDetail({ id, go, back }: any) { const { colors } = useTheme(); const { user } = useAuth(); const { add } = useCart(); const [data, setData] = useState<{ listing: Listing; related: Listing[]; vendorItems: Listing[] } | null>(null); const [reviews, setReviews] = useState<Review[]>([]); const [loading, setLoading] = useState(true); const [reviewOpen, setReviewOpen] = useState(false); const [review, setReview] = useState({ rating: '5', title: '', comment: '' });
  const load = useCallback(async () => { setLoading(true); try { const detail = await api.get<{listing: Listing; related: Listing[]; vendorItems: Listing[]}>(`/listings/${id}`); setData(detail); const result = await api.get<{reviews: Review[]}>(`/reviews${query({ listing_id: id, limit: 5 })}`); setReviews(result.reviews); } catch (e) { Alert.alert('Listing unavailable', message(e)); back(); } finally { setLoading(false); } }, [id, back]); useEffect(() => { void load(); }, [load]); if (loading || !data) return <View style={styles.page}><Header title="Listing" back={back}/><Spinner label="Loading listing…"/></View>; const listing = data.listing; const addItem = () => { if (!user) return go('login'); add({ listing_id: listing.id, vendor_id: listing.vendor_id, vendor_name: listing.business_name || 'Local seller', title: listing.title, price: Number(listing.price), currency: listing.currency, image: listing.images?.[0], qty: 1, max: listing.quantity ?? undefined, kind: listing.kind }); Alert.alert('Added to cart', `${listing.title} is ready for checkout.`); };
  const submitReview = async () => { try { await api.post('/reviews', { listing_id: id, rating: Number(review.rating), title: review.title || undefined, comment: review.comment || undefined }); setReviewOpen(false); setReview({ rating: '5', title: '', comment: '' }); await load(); Alert.alert('Thank you', 'Your review is now published.'); } catch (e) { Alert.alert('Cannot post review', message(e)); } };
  return <View style={styles.page}><Header title="Details" back={back}/><ScrollView contentContainerStyle={styles.detailScroll}>{listing.images?.length ? <ScrollView horizontal pagingEnabled showsHorizontalScrollIndicator={false}>{listing.images.map((url) => <Image key={url} source={{ uri: url }} style={styles.detailImage}/>)}</ScrollView> : <View style={[styles.detailImage, { backgroundColor: colors.primarySoft }]}><Ionicons name={listing.kind === 'service' ? 'construct-outline' : 'cube-outline'} size={62} color={colors.primary}/></View>}<View style={styles.detailBody}><View style={styles.kindLine}><Text style={[styles.kindTag, { color: listing.kind === 'service' ? colors.teal : colors.gold, backgroundColor: listing.kind === 'service' ? colors.tealSoft : colors.goldSoft }]}>{listing.kind.toUpperCase()}</Text>{listing.duration_mins ? <Text style={[styles.duration, { color: colors.text2 }]}>{listing.duration_mins} min</Text> : null}</View><Text style={[styles.detailTitle, { color: colors.text }]}>{listing.title}</Text><Money value={listing.price} currency={listing.currency} strong/><Text style={[styles.detailDescription, { color: colors.text2 }]}>{listing.description || 'Ask the seller for more details about this listing.'}</Text><Card style={{ marginTop: 15 }}><Pressable onPress={() => go('store', { slug: listing.vendor_slug })} style={styles.vendorRow}><View style={[styles.vendorAvatar, { backgroundColor: colors.primarySoft }]}>{listing.vendor_logo ? <Image source={{uri: listing.vendor_logo}} style={styles.vendorLogo}/> : <Ionicons name="storefront-outline" size={23} color={colors.primary}/>}</View><View style={{ flex: 1 }}><Text style={[styles.vendorName, { color: colors.text }]}>{listing.business_name}</Text><Text style={[styles.vendorMeta, { color: colors.text2 }]}>{listing.vendor_city} · View store</Text></View><Ionicons name="chevron-forward" size={20} color={colors.muted}/></Pressable></Card><SectionTitle title={`Reviews (${listing.rating_count || reviews.length})`}/>{reviews.length ? reviews.map((item) => <Card key={item.id} style={{ marginBottom: 9 }}><Text style={[styles.reviewStars, { color: colors.gold }]}>{'★'.repeat(item.rating)}<Text style={{ color: colors.border }}>{'★'.repeat(5-item.rating)}</Text></Text><Text style={[styles.reviewTitle, { color: colors.text }]}>{item.title || 'Buyer review'}</Text>{item.comment ? <Text style={[styles.reviewCopy, { color: colors.text2 }]}>{item.comment}</Text> : null}<Text style={[styles.reviewDate, { color: colors.muted }]}>{item.buyer_name || 'Verified buyer'} · {date(item.created_at)}</Text></Card>) : <Text style={[styles.noReview, { color: colors.text2 }]}>No reviews yet.</Text>}{user ? <Button variant="secondary" onPress={() => setReviewOpen(true)} style={{ marginTop: 2 }}>Write a review</Button> : null}<ListingRail title="You may also like" listings={data.related} onSelect={(newId) => go('listing', { id: newId })} onMore={() => go('browse')}/></View></ScrollView><View style={[styles.buyBar, { backgroundColor: colors.surface, borderColor: colors.border }]}>{listing.kind === 'service' ? <Button onPress={() => go('booking', { listing })}>Book this service</Button> : <Button onPress={addItem}>Add to cart</Button>}</View><Sheet visible={reviewOpen} title="Write a review" onClose={() => setReviewOpen(false)}><Field label="Rating (1–5)" value={review.rating} onChangeText={(rating) => setReview((r) => ({ ...r, rating }))} keyboardType="number-pad" maxLength={1}/><Field label="Review title (optional)" value={review.title} onChangeText={(title) => setReview((r) => ({ ...r, title }))} placeholder="Summarise your experience"/><Field label="Comment (optional)" value={review.comment} onChangeText={(comment) => setReview((r) => ({ ...r, comment }))} multiline style={{ minHeight: 96, textAlignVertical: 'top', paddingTop: 12 }}/><Button onPress={submitReview}>Post review</Button></Sheet></View>;
}

function StoreDetail({ slug, go, back }: any) { const { colors } = useTheme(); const [vendor, setVendor] = useState<Vendor | null>(null); const [listings, setListings] = useState<Listing[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { (async () => { try { const data = await api.get<{vendor: Vendor; listings: Listing[]}>(`/vendors/${encodeURIComponent(slug)}`); setVendor(data.vendor); setListings(data.listings); } catch (e) { Alert.alert('Store unavailable', message(e)); back(); } finally { setLoading(false); } })(); }, [slug, back]); if (loading || !vendor) return <View style={styles.page}><Header title="Store" back={back}/><Spinner label="Loading store…"/></View>; return <View style={styles.page}><Header title="Store" back={back}/><ScrollView contentContainerStyle={styles.detailScroll}><View style={[styles.storeHero, { backgroundColor: colors.primarySoft }]}>{vendor.logo_url ? <Image source={{uri: vendor.logo_url}} style={styles.storeLogo}/> : <Ionicons name="storefront" size={48} color={colors.primary}/>}</View><View style={styles.storeInfo}><Text style={[styles.detailTitle, { color: colors.text }]}>{vendor.business_name}</Text><Text style={[styles.detailDescription, { color: colors.text2 }]}>{vendor.description || 'A verified local Sokoni Hub seller.'}</Text><View style={styles.storeMeta}><Ionicons name="location-outline" size={17} color={colors.muted}/><Text style={[styles.vendorMeta, { color: colors.text2 }]}>{vendor.city}, {vendor.country}</Text></View><Button variant="secondary" onPress={() => Linking.openURL(`https://wa.me/${String(vendor.whatsapp || '').replace(/\D/g, '')}`)}>Message store on WhatsApp</Button><SectionTitle title="Available listings"/>{listings.length ? listings.map((listing) => <ListingCard key={listing.id} listing={listing} onPress={() => go('listing', { id: listing.id })}/>) : <EmptyState title="No current listings" text="Check back soon for this seller's latest products and services."/>}</View></ScrollView></View>; }

function Cart({ go, back, tab }: any) { const { colors } = useTheme(); const cart = useCart(); const subtotal = cart.items.reduce((total, item) => total + item.price * item.qty, 0); return <View style={styles.page}><Header title="Your cart" back={back}/>{cart.items.length ? <><ScrollView contentContainerStyle={styles.cartList}>{cart.items.map((item) => <Card key={item.listing_id} style={styles.cartItem}>{item.image ? <Image source={{uri: item.image}} style={styles.cartImage}/> : <View style={[styles.cartImage, { backgroundColor: colors.primarySoft }]}><Ionicons name="cube-outline" size={25} color={colors.primary}/></View>}<View style={{flex:1}}><Text numberOfLines={2} style={[styles.listingTitle, { color: colors.text }]}>{item.title}</Text><Text style={[styles.listingVendor, { color: colors.text2 }]}>{item.vendor_name}</Text><Money value={item.price} currency={item.currency}/><View style={styles.qtyRow}><Pressable onPress={() => item.qty === 1 ? cart.remove(item.listing_id) : cart.setQty(item.listing_id, item.qty - 1)} style={[styles.qtyButton, { borderColor: colors.border }]}><Ionicons name={item.qty === 1 ? 'trash-outline' : 'remove'} size={17} color={colors.text}/></Pressable><Text style={[styles.qty, { color: colors.text }]}>{item.qty}</Text><Pressable onPress={() => cart.setQty(item.listing_id, item.qty + 1)} style={[styles.qtyButton, { borderColor: colors.border }]}><Ionicons name="add" size={17} color={colors.text}/></Pressable></View></View></Card>)}</ScrollView><View style={[styles.cartFooter, { backgroundColor: colors.surface, borderColor: colors.border }]}><View><Text style={[styles.totalLabel, { color: colors.text2 }]}>Items subtotal</Text><Money value={subtotal} strong/></View><Button onPress={() => go('checkout')} style={{ minWidth: 155 }}>Checkout</Button></View></> : <><EmptyState title="Your cart is empty" text="Add products from local sellers and they will appear here." icon="bag-outline" action={<Button style={{ marginTop: 8 }} onPress={() => tab('browse')}>Browse marketplace</Button>}/><Tabs active="cart" tab={tab}/></>}</View>; }

function Checkout({ go, back }: any) { const { colors } = useTheme(); const { user } = useAuth(); const cart = useCart(); const [mode, setMode] = useState<'delivery' | 'pickup'>('delivery'); const [quote, setQuote] = useState<CartQuote | null>(null); const [busy, setBusy] = useState(false); const [form, setForm] = useState({ contact_name: user?.full_name || '', contact_phone: user?.phone || '', delivery_address: '', city: 'Doha', country: 'Qatar', payment_method: 'cash_on_delivery' as PaymentMethod, note: '' }); const set = (key: keyof typeof form) => (value: string) => setForm((old) => ({ ...old, [key]: value })); const quoteCart = useCallback(async () => { try { setQuote(await api.post<CartQuote>('/orders/quote', { items: cart.items.map((item) => ({ listing_id: item.listing_id, qty: item.qty })), fulfilment_mode: mode })); } catch (e) { Alert.alert('Cart changed', message(e)); } }, [cart.items, mode]); useEffect(() => { if (!cart.items.length) { back(); return; } void quoteCart(); }, [quoteCart, cart.items.length, back]); const order = async () => { if (!user) return go('login'); if (!form.contact_name || !form.contact_phone || (mode === 'delivery' && form.delivery_address.length < 5)) return Alert.alert('Complete checkout', 'Provide your contact details and a full delivery address.'); setBusy(true); try { const result = await api.post<{orders: Order[]; whatsapp_urls?: string[]}>('/orders/checkout', { request_id: randomUUID(), items: cart.items.map((item) => ({ listing_id: item.listing_id, qty: item.qty })), fulfilment_mode: mode, ...form, attribution: { source: 'mobile_app' } }); cart.clear(); Alert.alert('Order placed', `${result.orders.length} order${result.orders.length === 1 ? '' : 's'} created. You can track them anytime from your account.`, [{ text: 'View orders', onPress: () => go('orders') }]); } catch (e) { Alert.alert('Could not place order', message(e)); } finally { setBusy(false); } }; return <View style={styles.page}><Header title="Checkout" back={back}/><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.checkoutScroll}><Notice>Final prices and availability are confirmed securely by the server before an order is placed.</Notice><Text style={[styles.checkoutHeading, { color: colors.text }]}>Fulfilment</Text><View style={styles.checkoutModes}><Chip selected={mode === 'delivery'} onPress={() => setMode('delivery')}>Delivery</Chip><Chip selected={mode === 'pickup'} onPress={() => setMode('pickup')}>Pickup</Chip></View><Text style={[styles.checkoutHeading, { color: colors.text }]}>Contact details</Text><Field label="Full name" value={form.contact_name} onChangeText={set('contact_name')} /><Field label="Phone number" value={form.contact_phone} onChangeText={set('contact_phone')} keyboardType="phone-pad"/>{mode === 'delivery' && <><Field label="Delivery address" value={form.delivery_address} onChangeText={set('delivery_address')} multiline placeholder="Building, street, area"/><View style={styles.priceFields}><View style={{flex:1}}><Field label="City" value={form.city} onChangeText={set('city')}/></View><View style={{flex:1}}><Field label="Country" value={form.country} onChangeText={set('country')}/></View></View></>}<Text style={[styles.checkoutHeading, { color: colors.text }]}>Payment</Text>{([['cash_on_delivery','Cash on delivery'],['whatsapp','Confirm on WhatsApp'],['bank_transfer','Bank transfer']] as [PaymentMethod,string][]).map(([value, label]) => <Pressable key={value} onPress={() => setForm((old) => ({ ...old, payment_method: value }))} style={[styles.paymentOption, { backgroundColor: colors.surface, borderColor: form.payment_method === value ? colors.primary : colors.border }]}><Ionicons name={form.payment_method === value ? 'radio-button-on' : 'radio-button-off'} size={20} color={form.payment_method === value ? colors.primary : colors.muted}/><Text style={[styles.paymentText, { color: colors.text }]}>{label}</Text></Pressable>)}<Field label="Note for seller (optional)" value={form.note} onChangeText={set('note')} multiline placeholder="Any helpful instructions"/>{quote ? <Card style={styles.quoteCard}><Text style={[styles.quoteTitle, { color: colors.text }]}>Order estimate</Text>{quote.vendors.map((vendor) => <View key={vendor.vendor_id} style={styles.quoteVendor}><Text style={[styles.vendorMeta, { color: colors.text2 }]}>{vendor.vendor_name}</Text><Money value={vendor.total} currency={vendor.currency}/></View>)}<Divider/><View style={styles.quoteTotal}><Text style={[styles.totalLabel, { color: colors.text }]}>Total</Text><Money value={quote.total} currency={quote.currency} strong/></View></Card> : <Spinner label="Confirming current prices…"/>}<Button loading={busy} onPress={order} style={{ marginTop: 12 }}>Place secure order</Button></ScrollView></View>; }

function Orders({ go, back }: any) { const { colors } = useTheme(); const { user } = useAuth(); const [orders, setOrders] = useState<Order[]>([]); const [loading, setLoading] = useState(true); const load = useCallback(async () => { if (!user) return; setLoading(true); try { setOrders((await api.get<{orders: Order[]}>('/orders/mine')).orders); } catch (e) { Alert.alert('Could not load orders', message(e)); } finally { setLoading(false); } }, [user]); useEffect(() => { void load(); }, [load]); if (!user) return <GuestGate title="Sign in to see orders" text="Your order history and status are stored securely in your buyer account." go={go} back={back}/>; return <View style={styles.page}><Header title="My orders" back={back}/>{loading ? <Spinner label="Loading your orders…"/> : <FlatList data={orders} keyExtractor={(order) => order.id} contentContainerStyle={styles.ordersList} refreshControl={<RefreshControl refreshing={loading} onRefresh={load} tintColor={colors.primary}/>} renderItem={({ item }) => <Card style={styles.orderCard}><View style={styles.orderTop}><View><Text style={[styles.orderCode, { color: colors.text }]}>{item.code}</Text><Text style={[styles.orderDate, { color: colors.text2 }]}>{date(item.created_at)} · {item.business_name || item.vendor?.business_name}</Text></View><Status value={item.status}/></View><Divider/><View style={styles.orderBottom}><Money value={item.total} currency={item.currency} strong/><Pressable onPress={() => go('track', { code: item.code, phone: user.phone })}><Text style={[styles.trackLink, { color: colors.primary }]}>Track order</Text></Pressable></View></Card>} ListEmptyComponent={<EmptyState title="No orders yet" text="When you purchase a local product, its status will appear here." action={<Button onPress={() => go('browse')}>Start browsing</Button>}/>}/>}</View>; }
function Bookings({ go, back }: any) { const { colors } = useTheme(); const { user } = useAuth(); const [bookings, setBookings] = useState<Booking[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { if (!user) return; api.get<{bookings: Booking[]}>('/bookings/mine').then((r) => setBookings(r.bookings)).catch((e) => Alert.alert('Could not load bookings', message(e))).finally(() => setLoading(false)); }, [user]); if (!user) return <GuestGate title="Sign in to see bookings" text="Keep your service requests and their latest status in one place." go={go} back={back}/>; return <View style={styles.page}><Header title="My bookings" back={back}/>{loading ? <Spinner label="Loading your bookings…"/> : <FlatList data={bookings} keyExtractor={(booking) => booking.id} contentContainerStyle={styles.ordersList} renderItem={({ item }) => <Card style={styles.orderCard}><View style={styles.orderTop}><View><Text style={[styles.orderCode, { color: colors.text }]}>{item.listing_title || item.code}</Text><Text style={[styles.orderDate, { color: colors.text2 }]}>{item.business_name} · {date(item.slot_starts_at || item.scheduled_at || item.preferred_at)}</Text></View><Status value={item.status}/></View><Divider/><Pressable onPress={() => go('track', { bookingCode: item.code, phone: user.phone })}><Text style={[styles.trackLink, { color: colors.primary }]}>Track booking</Text></Pressable></Card>} ListEmptyComponent={<EmptyState title="No bookings yet" text="Book a local service to manage it here." action={<Button onPress={() => go('browse', { kind: 'service' })}>Browse services</Button>}/>}/>}</View>; }
function Status({ value }: { value: string }) { const { colors } = useTheme(); const danger = value === 'cancelled'; const success = ['delivered','completed','confirmed'].includes(value); return <View style={[styles.status, { backgroundColor: danger ? colors.dangerSoft : success ? colors.successSoft : colors.warningSoft }]}><Text style={{ color: danger ? colors.danger : success ? colors.success : colors.warning, fontSize: 11, fontWeight: '800' }}>{statusLabel(value)}</Text></View>; }
function Track({ go, back, params }: any) { const { colors } = useTheme(); const [orderCode, setOrderCode] = useState(params?.code || ''); const [bookingCode, setBookingCode] = useState(params?.bookingCode || ''); const [phone, setPhone] = useState(params?.phone || ''); const [result, setResult] = useState<any>(null); const [busy, setBusy] = useState(false); const track = async () => { if (!phone || (!orderCode && !bookingCode)) return Alert.alert('Enter tracking details', 'Use either your order or booking code and the phone used at checkout.'); setBusy(true); try { const isBooking = !!bookingCode; const data = await api.get<any>(isBooking ? `/bookings/track${query({code: bookingCode, phone})}` : `/orders/track${query({code: orderCode, phone})}`); setResult({ ...data, isBooking }); } catch (e) { Alert.alert('Could not find it', message(e)); } finally { setBusy(false); } }; return <View style={styles.page}><Header title="Track an order or booking" back={back}/><ScrollView contentContainerStyle={styles.trackScroll}><Notice>Enter the code from your confirmation and the complete phone number used to place it.</Notice><Field label="Order code (if tracking an order)" value={orderCode} onChangeText={(value) => { setOrderCode(value.toUpperCase()); if(value) setBookingCode(''); }} autoCapitalize="characters" placeholder="ORD…"/><Field label="Booking code (if tracking a service)" value={bookingCode} onChangeText={(value) => { setBookingCode(value.toUpperCase()); if(value) setOrderCode(''); }} autoCapitalize="characters" placeholder="BKG…"/><Field label="Phone number" value={phone} onChangeText={setPhone} keyboardType="phone-pad" placeholder="+974…"/><Button loading={busy} onPress={track}>Track status</Button>{result ? <Card style={{ marginTop: 18 }}><View style={styles.orderTop}><Text style={[styles.orderCode, { color: colors.text }]}>{result.order?.code || result.booking?.code}</Text><Status value={result.order?.status || result.booking?.status}/></View><Divider/><Text style={[styles.trackProduct, { color: colors.text }]}>{result.order?.business_name || result.booking?.listing_title || result.booking?.business_name || 'Sokoni Hub'}</Text><Text style={[styles.trackDetail, { color: colors.text2 }]}>{result.isBooking ? `Preferred: ${date(result.booking?.slot_starts_at || result.booking?.scheduled_at || result.booking?.preferred_at)}` : `Placed: ${date(result.order?.created_at)}`}</Text>{result.order?.whatsapp_url ? <Button variant="secondary" onPress={() => Linking.openURL(result.order.whatsapp_url)} style={{ marginTop: 13 }}>Contact seller on WhatsApp</Button> : null}</Card> : null}</ScrollView></View>; }
function BookService({ listing, go, back }: any) { const { colors } = useTheme(); const { user } = useAuth(); const [form, setForm] = useState({ contact_name: user?.full_name || '', contact_phone: user?.phone || '', contact_email: user?.email || '', preferred_at: '', preferred_note: '', location_type: 'vendor', address: '' }); const [busy, setBusy] = useState(false); const set = (key: keyof typeof form) => (value: string) => setForm((old) => ({...old, [key]: value})); const submit = async () => { if (!user) return go('login'); if (!form.contact_name || !form.contact_phone) return Alert.alert('Add your details', 'Your name and phone are required for a booking.'); setBusy(true); try { const response = await api.post<{booking: Booking; whatsapp?: string}>('/bookings', { ...form, listing_id: listing.id, preferred_at: form.preferred_at ? new Date(form.preferred_at).toISOString() : undefined, address: form.location_type === 'home' ? form.address : undefined }); Alert.alert('Booking requested', `Your code is ${response.booking.code}. The provider will confirm details with you.`, [{ text: 'View bookings', onPress: () => go('bookings') }]); } catch (e) { Alert.alert('Could not book service', message(e)); } finally { setBusy(false); } }; if (!listing) return <View style={styles.page}><Header title="Book service" back={back}/><EmptyState title="Service unavailable" text="Return to the marketplace and choose a service."/></View>; return <View style={styles.page}><Header title="Book service" back={back}/><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.checkoutScroll}><Card><Text style={[styles.listingTitle, {color: colors.text}]}>{listing.title}</Text><Money value={listing.price} currency={listing.currency} strong/><Text style={[styles.vendorMeta, {color: colors.text2}]}>{listing.business_name}</Text></Card><Text style={[styles.checkoutHeading, {color: colors.text}]}>Your request</Text><Field label="Full name" value={form.contact_name} onChangeText={set('contact_name')}/><Field label="Phone number" value={form.contact_phone} onChangeText={set('contact_phone')} keyboardType="phone-pad"/><Field label="Email (optional)" value={form.contact_email} onChangeText={set('contact_email')} keyboardType="email-address" autoCapitalize="none"/><Field label="Preferred date and time (optional)" value={form.preferred_at} onChangeText={set('preferred_at')} placeholder="YYYY-MM-DD HH:MM"/><View style={styles.checkoutModes}><Chip selected={form.location_type === 'vendor'} onPress={() => set('location_type')('vendor')}>At provider</Chip><Chip selected={form.location_type === 'home'} onPress={() => set('location_type')('home')}>At my location</Chip></View>{form.location_type === 'home' && <Field label="Service address" value={form.address} onChangeText={set('address')} multiline placeholder="Building, street, area"/>}<Field label="Notes (optional)" value={form.preferred_note} onChangeText={set('preferred_note')} multiline placeholder="Anything the provider should know"/><Notice>Requested times are confirmed by the provider. You can track the booking after it is created.</Notice><Button loading={busy} onPress={submit} style={{ marginTop: 14 }}>Request booking</Button></ScrollView></View>; }

function Account({ go, back, tab }: any) { const { colors, theme, toggleTheme } = useTheme(); const { user, logout } = useAuth(); const open = (url: string) => WebBrowser.openBrowserAsync(url); if (!user) return <View style={styles.page}><Header title="Account" back={back}/><EmptyState icon="person-outline" title="Your Sokoni Hub account" text="Sign in to order, book services, save your profile and see live updates." action={<View style={{ width: 235, gap: 10, marginTop: 10 }}><Button onPress={() => go('login')}>Sign in</Button><Button variant="secondary" onPress={() => go('register')}>Create an account</Button></View>}/><Tabs active="account" tab={tab}/></View>; return <View style={styles.page}><Header title="Account" back={back}/><ScrollView contentContainerStyle={styles.accountScroll}><View style={[styles.profileHero, { backgroundColor: colors.primary }]}><View style={[styles.profileAvatar, { backgroundColor: colors.gold }]}><Text style={styles.profileInitial}>{user.full_name.charAt(0).toUpperCase()}</Text></View><View><Text style={styles.profileName}>{user.full_name}</Text><Text style={styles.profileContact}>{user.email || user.phone}</Text></View></View><AccountRow icon="receipt-outline" title="My orders" subtitle="Track products and delivery" onPress={() => go('orders')}/><AccountRow icon="calendar-outline" title="My bookings" subtitle="Manage service requests" onPress={() => go('bookings')}/><AccountRow icon="navigate-outline" title="Track with a code" subtitle="Find an order or booking" onPress={() => go('track')}/><Divider/><AccountRow icon={theme === 'dark' ? 'moon-outline' : 'sunny-outline'} title="Appearance" subtitle={`${theme === 'dark' ? 'Dark' : 'Light'} theme — tap to change`} onPress={toggleTheme}/><AccountRow icon="help-buoy-outline" title="Help & support" subtitle="Contact Sokoni Hub or report an issue" onPress={() => go('support')}/><AccountRow icon="document-text-outline" title="Terms & privacy" subtitle="Read our customer policies" onPress={() => open(`${WEB_URL}/legal`)}/><Divider/><Button variant="danger" onPress={() => Alert.alert('Sign out?', 'You will need your password and PIN to sign in again.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Sign out', style: 'destructive', onPress: () => void logout() }])}>Sign out</Button><Text style={[styles.accountFootnote, { color: colors.muted }]}>Vendors and administrators use the secure web portal; this app is designed only for shoppers.</Text></ScrollView><Tabs active="account" tab={tab}/></View>; }
function AccountRow({ icon, title, subtitle, onPress }: { icon: keyof typeof Ionicons.glyphMap; title: string; subtitle: string; onPress: () => void }) { const { colors } = useTheme(); return <Pressable onPress={onPress} style={styles.accountRow}><View style={[styles.accountIcon, { backgroundColor: colors.primarySoft }]}><Ionicons name={icon} size={21} color={colors.primary}/></View><View style={{ flex: 1 }}><Text style={[styles.accountTitle, { color: colors.text }]}>{title}</Text><Text style={[styles.accountSubtitle, { color: colors.text2 }]}>{subtitle}</Text></View><Ionicons name="chevron-forward" size={20} color={colors.muted}/></Pressable>; }
function Support({ back }: any) { const { colors } = useTheme(); return <View style={styles.page}><Header title="Help & support" back={back}/><ScrollView contentContainerStyle={styles.supportScroll}><View style={[styles.supportHero, { backgroundColor: colors.tealSoft }]}><Ionicons name="help-buoy" size={38} color={colors.teal}/><Text style={[styles.supportTitle, { color: colors.text }]}>We're here to help</Text><Text style={[styles.supportCopy, { color: colors.text2 }]}>For help with an order, booking, account or marketplace issue, contact Sokoni Hub directly.</Text></View><AccountRow icon="logo-whatsapp" title="WhatsApp support" subtitle="Message our support team" onPress={() => Linking.openURL(`https://wa.me/${SUPPORT_WHATSAPP}`)}/><AccountRow icon="mail-outline" title="Email support" subtitle={SUPPORT_EMAIL} onPress={() => Linking.openURL(`mailto:${SUPPORT_EMAIL}`)}/><AccountRow icon="globe-outline" title="Open customer website" subtitle="More help and legal information" onPress={() => WebBrowser.openBrowserAsync(WEB_URL)}/><Notice type="warning">Never share your password, PIN, one-time recovery code or payment details in a message.</Notice></ScrollView></View>; }
function GuestGate({ title, text, go, back }: { title: string; text: string; go: any; back: any }) { return <View style={styles.page}><Header title="Your activity" back={back}/><EmptyState title={title} text={text} icon="lock-closed-outline" action={<Button style={{ marginTop: 10 }} onPress={() => go('login')}>Sign in</Button>}/></View>; }
function WebOnlyAccount({ onSignOut }: { onSignOut: () => Promise<void> }) { const { colors } = useTheme(); return <View style={styles.page}><Header title="Web portal account"/><EmptyState icon="desktop-outline" title="This account uses the web portal" text="Sokoni Hub's mobile application is intentionally for consumers only. Vendor and administrator tools remain protected on the web." action={<View style={{ width: 260, gap: 10, marginTop: 10 }}><Button onPress={() => WebBrowser.openBrowserAsync(WEB_URL)}>Open secure web portal</Button><Button variant="secondary" onPress={() => void onSignOut()}>Sign out</Button></View>}/><Text style={[styles.webPortalText, { color: colors.muted }]}>This separation keeps store operations and administration out of the consumer app.</Text></View>; }

